def main():
    existing = get_existing_norms(exclude_slugs={"cv-alphabet-a"})
    entries = []
    skipped = 0

    for item in WORDS_A:
        head = item[0]
        norm = norm_vocab(head)
        if norm in existing:
            skipped += 1
            continue

        pos_type = item[1]

        if pos_type in ("noun", "verb"):
            level = item[3]
            msa = item[4]
            eg = item[5]
            ex_es = item[6]
            ex_ar = item[7]
            domain = item[8] if len(item) > 8 else "daily"
            if pos_type == "noun":
                gender = item[2]
                entry = make_noun(head, gender, level, msa, eg, ex_es, ex_ar, domain=domain, rank=5)
            else:
                paradigm = item[2]
                entry = make_verb(head, paradigm, level, msa, eg, ex_es, ex_ar, domain=domain, rank=5)
        elif pos_type in ("adj", "adv"):
            level = item[2]
            msa = item[3]
            eg = item[4]
            ex_es = item[5]
            ex_ar = item[6]
            domain = item[7] if len(item) > 7 else "daily"
            if pos_type == "adj":
                entry = make_adj(head, level, msa, eg, ex_es, ex_ar, domain=domain, rank=5)
            else:
                entry = make_adv(head, level, msa, eg, ex_es, ex_ar, domain=domain, rank=5)
        else:
            continue

        entries.append(entry)
        existing.add(norm)

    print(f"Alphabet A: Prepared {len(entries)} new entries (skipped {skipped} existing).")
    emit_bundle("vocab-cv-alphabet-a.json", "cv-alphabet-a", "حزمة الحرف A الشاملة في المعجم الإسباني", entries)

if __name__ == "__main__":
    main()
